// Generated by scripts/embed-schema.ts from contracts/schema.graphql. Do not edit.
export const schemaSDL = "\"\"\"\nOrder Fulfillment Lab GraphQL contract.\n\nThis file is the single source of truth. All three implementations serve it\nunchanged, and TypeScript types are generated from it (packages/graphql-types).\n\nError model:\n- Expected business outcomes are union members that implement DomainError\n  (for example InsufficientStock). Clients switch on __typename.\n- Cross-cutting failures are GraphQL errors with extensions.code:\n  UNAUTHENTICATED, FORBIDDEN, NOT_FOUND, BAD_USER_INPUT (with\n  extensions.fieldErrors), QUERY_TOO_COMPLEX, SEARCH_UNAVAILABLE,\n  RATE_LIMITED, INTERNAL_SERVER_ERROR.\n\"\"\"\nschema {\n  query: Query\n  mutation: Mutation\n  subscription: Subscription\n}\n\n\"ISO-8601 timestamp in UTC, for example 2026-11-25T10:00:00.000Z.\"\nscalar DateTime\n\nenum Role {\n  CUSTOMER\n  OPERATOR\n  ADMIN\n}\n\n\"Money in integer minor units (cents). The lab uses one currency: USD.\"\ntype Money {\n  amountMinor: Int!\n  currency: String!\n  \"Display string such as $12.50. Formatting only; never parse it.\"\n  formatted: String!\n}\n\ntype User {\n  id: ID!\n  email: String!\n  displayName: String!\n  role: Role!\n}\n\ntype PageInfo {\n  hasNextPage: Boolean!\n  endCursor: String\n}\n\ninterface DomainError {\n  code: String!\n  message: String!\n}\n\n# ---------------------------------------------------------------------------\n# Catalog\n# ---------------------------------------------------------------------------\n\ntype Category {\n  id: ID!\n  slug: String!\n  name: String!\n}\n\ntype Warehouse {\n  id: ID!\n  code: String!\n  name: String!\n}\n\ntype Product {\n  id: ID!\n  slug: String!\n  name: String!\n  description: String!\n  category: Category!\n  skus: [Sku!]!\n  \"Lowest active SKU price.\"\n  fromPrice: Money!\n  \"Sum of available units across all SKUs and warehouses (PostgreSQL, authoritative).\"\n  availableQuantity: Int!\n}\n\ntype Sku {\n  id: ID!\n  code: String!\n  label: String!\n  price: Money!\n  product: Product!\n  \"Per-warehouse availability. Read from PostgreSQL.\"\n  stock: [StockLevel!]!\n  availableQuantity: Int!\n}\n\ntype StockLevel {\n  warehouse: Warehouse!\n  onHand: Int!\n  reserved: Int!\n  available: Int!\n}\n\n# ---------------------------------------------------------------------------\n# Search (Elasticsearch, eventually consistent)\n# ---------------------------------------------------------------------------\n\nenum ProductSort {\n  RELEVANCE\n  PRICE_ASC\n  PRICE_DESC\n  NEWEST\n}\n\ninput ProductSearchInput {\n  \"Free text. Empty means match all.\"\n  text: String\n  categorySlugs: [String!]\n  \"Inclusive.\"\n  minPriceMinor: Int\n  \"Exclusive.\"\n  maxPriceMinor: Int\n  inStockOnly: Boolean\n  sort: ProductSort = RELEVANCE\n}\n\ntype ProductSearchHit {\n  productId: ID!\n  slug: String!\n  name: String!\n  categorySlug: String!\n  categoryName: String!\n  fromPrice: Money!\n  \"Snapshot from the search index. Checkout always rechecks PostgreSQL.\"\n  inStock: Boolean!\n  score: Float\n}\n\ntype ProductSearchEdge {\n  cursor: String!\n  node: ProductSearchHit!\n}\n\n\"\"\"\nFacet bucket. value formats (stable contract):\n- categories: the category slug.\n- priceRanges: \"<minMinor>-<maxMinor>\" in integer minor units, min inclusive,\n  max exclusive, max empty when open-ended. Buckets: \"0-2500\", \"2500-5000\",\n  \"5000-10000\", \"10000-25000\", \"25000-\". Clients map a selection to\n  minPriceMinor / maxPriceMinor (maxPriceMinor is exclusive).\n- availability: \"in_stock\" | \"out_of_stock\". \"in_stock\" maps to inStockOnly: true.\n\"\"\"\ntype FacetBucket {\n  value: String!\n  label: String!\n  count: Int!\n  selected: Boolean!\n}\n\n\"\"\"\nFacet counts. For each dimension, counts apply every active filter except\nthe filter of that same dimension (disjunctive faceting), so users can see\nhow many results another choice in the same group would give.\n\"\"\"\ntype SearchFacets {\n  categories: [FacetBucket!]!\n  priceRanges: [FacetBucket!]!\n  availability: [FacetBucket!]!\n}\n\ntype ProductSearchConnection {\n  edges: [ProductSearchEdge!]!\n  pageInfo: PageInfo!\n  \"Exact up to 10000, then a lower bound.\"\n  totalCount: Int!\n  facets: SearchFacets!\n}\n\ntype ProductSuggestion {\n  productId: ID!\n  slug: String!\n  name: String!\n}\n\n# ---------------------------------------------------------------------------\n# Orders\n# ---------------------------------------------------------------------------\n\nenum OrderStatus {\n  PENDING_PAYMENT\n  CONFIRMED\n  PARTIALLY_SHIPPED\n  SHIPPED\n  CANCELLED\n}\n\nenum CancellationReason {\n  CUSTOMER_REQUEST\n  PAYMENT_DECLINED\n  RESERVATION_EXPIRED\n  OPERATOR_REQUEST\n}\n\nenum ReservationStatus {\n  ACTIVE\n  CONFIRMED\n  SHIPPED\n  RELEASED\n}\n\nenum PaymentStatus {\n  PENDING\n  CAPTURED\n  DECLINED\n  PARTIALLY_REFUNDED\n  REFUNDED\n}\n\nenum ReturnStatus {\n  REQUESTED\n  RECEIVED\n  REFUNDED\n}\n\ntype Order {\n  id: ID!\n  \"Human-readable number, for example ORD-100042.\"\n  number: String!\n  status: OrderStatus!\n  cancellationReason: CancellationReason\n  customer: User!\n  lines: [OrderLine!]!\n  subtotal: Money!\n  total: Money!\n  reservationExpiresAt: DateTime!\n  reservations: [Reservation!]!\n  payment: Payment\n  shipments: [Shipment!]!\n  returns: [Return!]!\n  \"Computed on the server from the order state and the viewer's role.\"\n  allowedActions: OrderActions!\n  createdAt: DateTime!\n  updatedAt: DateTime!\n}\n\ntype OrderActions {\n  canCancel: Boolean!\n  canRequestReturn: Boolean!\n  \"Warehouses that have confirmed, unshipped reservations (operators only).\"\n  shippableWarehouses: [Warehouse!]!\n  \"Returns in REQUESTED status that the viewer may receive (operators only; empty for customers).\"\n  receivableReturnIds: [ID!]!\n}\n\ntype OrderLine {\n  id: ID!\n  lineNumber: Int!\n  sku: Sku!\n  productName: String!\n  skuCode: String!\n  quantity: Int!\n  unitPrice: Money!\n  lineTotal: Money!\n  shippedQuantity: Int!\n  returnedQuantity: Int!\n  \"shippedQuantity minus quantity on returns (any status).\"\n  returnableQuantity: Int!\n}\n\ntype Reservation {\n  id: ID!\n  sku: Sku!\n  warehouse: Warehouse!\n  quantity: Int!\n  status: ReservationStatus!\n  expiresAt: DateTime!\n}\n\ntype Payment {\n  id: ID!\n  status: PaymentStatus!\n  amount: Money!\n  refunded: Money!\n  declineReason: String\n}\n\ntype Shipment {\n  id: ID!\n  warehouse: Warehouse!\n  trackingCode: String!\n  shippedAt: DateTime!\n  lines: [ShipmentLine!]!\n}\n\ntype ShipmentLine {\n  orderLineId: ID!\n  skuCode: String!\n  quantity: Int!\n}\n\ntype Return {\n  id: ID!\n  status: ReturnStatus!\n  reason: String!\n  refund: Money!\n  lines: [ReturnLine!]!\n  createdAt: DateTime!\n  receivedAt: DateTime\n  refundedAt: DateTime\n}\n\ntype ReturnLine {\n  orderLineId: ID!\n  skuCode: String!\n  warehouse: Warehouse!\n  quantity: Int!\n}\n\ntype OrderEdge {\n  cursor: String!\n  node: Order!\n}\n\ntype OrderConnection {\n  edges: [OrderEdge!]!\n  pageInfo: PageInfo!\n}\n\ninput OrderFilter {\n  status: [OrderStatus!]\n  \"Operators only: orders with confirmed, unshipped reservations in this warehouse.\"\n  awaitingShipmentFromWarehouseId: ID\n  \"Operators only: orders with at least one return in REQUESTED status.\"\n  withReturnsAwaitingReceipt: Boolean\n}\n\n# ---------------------------------------------------------------------------\n# Inventory\n# ---------------------------------------------------------------------------\n\nenum InventoryMovementKind {\n  RECEIPT\n  RESERVE\n  RELEASE\n  SHIP\n  RETURN_RESTOCK\n  ADJUSTMENT\n}\n\ntype InventoryBalance {\n  sku: Sku!\n  warehouse: Warehouse!\n  onHand: Int!\n  reserved: Int!\n  available: Int!\n  updatedAt: DateTime!\n}\n\ntype InventoryBalanceEdge {\n  cursor: String!\n  node: InventoryBalance!\n}\n\ntype InventoryBalanceConnection {\n  edges: [InventoryBalanceEdge!]!\n  pageInfo: PageInfo!\n}\n\ntype InventoryMovement {\n  id: ID!\n  sku: Sku!\n  warehouse: Warehouse!\n  kind: InventoryMovementKind!\n  onHandDelta: Int!\n  reservedDelta: Int!\n  referenceType: String\n  referenceId: ID\n  reason: String\n  actor: User\n  createdAt: DateTime!\n}\n\ntype InventoryMovementEdge {\n  cursor: String!\n  node: InventoryMovement!\n}\n\ntype InventoryMovementConnection {\n  edges: [InventoryMovementEdge!]!\n  pageInfo: PageInfo!\n}\n\n# ---------------------------------------------------------------------------\n# Operations (administrator)\n# ---------------------------------------------------------------------------\n\nenum JobStatus {\n  PENDING\n  PROCESSING\n  DONE\n  FAILED\n}\n\ntype Job {\n  id: ID!\n  topic: String!\n  aggregateType: String!\n  aggregateId: String!\n  status: JobStatus!\n  attempts: Int!\n  maxAttempts: Int!\n  lastError: String\n  availableAt: DateTime!\n  createdAt: DateTime!\n}\n\ntype JobEdge {\n  cursor: String!\n  node: Job!\n}\n\ntype JobConnection {\n  edges: [JobEdge!]!\n  pageInfo: PageInfo!\n}\n\ntype OrderStatusCount {\n  status: OrderStatus!\n  count: Int!\n}\n\ntype DailyRevenue {\n  \"UTC date, YYYY-MM-DD.\"\n  day: String!\n  orders: Int!\n  revenue: Money!\n  \"Running total across the reported window (window function).\"\n  cumulativeRevenue: Money!\n}\n\ntype LowStockItem {\n  sku: Sku!\n  warehouse: Warehouse!\n  available: Int!\n}\n\ntype OperationsSummary {\n  ordersByStatus: [OrderStatusCount!]!\n  dailyRevenue(days: Int = 14): [DailyRevenue!]!\n  lowStock(threshold: Int = 5, limit: Int = 20): [LowStockItem!]!\n  pendingJobs: Int!\n  failedJobs: Int!\n  \"Age in seconds of the oldest claimable job; 0 when the backlog is empty.\"\n  oldestPendingJobAgeSeconds: Int!\n  expiredActiveReservations: Int!\n}\n\ntype AuditEntry {\n  id: ID!\n  actor: User\n  action: String!\n  entityType: String!\n  entityId: String!\n  details: String!\n  correlationId: String\n  createdAt: DateTime!\n}\n\ntype AuditEntryEdge {\n  cursor: String!\n  node: AuditEntry!\n}\n\ntype AuditEntryConnection {\n  edges: [AuditEntryEdge!]!\n  pageInfo: PageInfo!\n}\n\n# ---------------------------------------------------------------------------\n# Queries\n# ---------------------------------------------------------------------------\n\ntype Query {\n  \"Null when not signed in.\"\n  viewer: User\n\n  categories: [Category!]!\n  warehouses: [Warehouse!]!\n  product(slug: String!): Product\n  \"Elasticsearch. first is limited to 1..50.\"\n  searchProducts(input: ProductSearchInput, first: Int = 20, after: String): ProductSearchConnection!\n  \"Elasticsearch autocomplete. limit is limited to 1..10.\"\n  productSuggestions(prefix: String!, limit: Int = 5): [ProductSuggestion!]!\n\n  \"Owner, operator, or administrator. NOT_FOUND for other customers.\"\n  order(id: ID!): Order\n  \"Orders of the signed-in customer, newest first. first is limited to 1..50.\"\n  myOrders(first: Int = 20, after: String, filter: OrderFilter): OrderConnection!\n  \"Operator or administrator. All orders, newest first.\"\n  orders(first: Int = 20, after: String, filter: OrderFilter): OrderConnection!\n\n  \"Operator or administrator.\"\n  inventory(warehouseId: ID, lowStockOnly: Boolean = false, first: Int = 20, after: String): InventoryBalanceConnection!\n  \"Operator or administrator. Newest first.\"\n  inventoryMovements(skuId: ID!, warehouseId: ID, first: Int = 20, after: String): InventoryMovementConnection!\n\n  \"Administrator.\"\n  operationsSummary: OperationsSummary!\n  \"Administrator.\"\n  jobs(status: JobStatus = FAILED, first: Int = 20, after: String): JobConnection!\n  \"Administrator.\"\n  auditLog(first: Int = 20, after: String): AuditEntryConnection!\n}\n\n# ---------------------------------------------------------------------------\n# Mutations\n# ---------------------------------------------------------------------------\n\ninput CheckoutLineInput {\n  skuId: ID!\n  quantity: Int!\n  \"The price the customer saw. A mismatch returns PriceChanged.\"\n  expectedUnitPriceMinor: Int!\n}\n\ninput CheckoutInput {\n  \"Client-generated. Retries with the same key return the same result.\"\n  idempotencyKey: String!\n  lines: [CheckoutLineInput!]!\n  \"Simulated card token: tok_approve, tok_decline, or tok_slow_approve.\"\n  paymentToken: String!\n}\n\ntype CheckoutSucceeded {\n  order: Order!\n  \"True when this response replays an earlier request with the same key.\"\n  replayed: Boolean!\n}\n\ntype InsufficientStockLine {\n  skuId: ID!\n  requested: Int!\n  available: Int!\n}\n\ntype InsufficientStock implements DomainError {\n  code: String!\n  message: String!\n  lines: [InsufficientStockLine!]!\n}\n\ntype PriceChangedLine {\n  skuId: ID!\n  expectedUnitPriceMinor: Int!\n  currentUnitPrice: Money!\n}\n\ntype PriceChanged implements DomainError {\n  code: String!\n  message: String!\n  lines: [PriceChangedLine!]!\n}\n\ntype IdempotencyKeyReused implements DomainError {\n  code: String!\n  message: String!\n}\n\nunion CheckoutResult = CheckoutSucceeded | InsufficientStock | PriceChanged | IdempotencyKeyReused\n\ntype OrderCancelled {\n  order: Order!\n}\n\ntype OrderNotCancellable implements DomainError {\n  code: String!\n  message: String!\n  status: OrderStatus!\n}\n\nunion CancelOrderResult = OrderCancelled | OrderNotCancellable\n\ninput ShipOrderInput {\n  orderId: ID!\n  warehouseId: ID!\n  trackingCode: String\n}\n\ntype ShipmentCreated {\n  shipment: Shipment!\n  order: Order!\n}\n\ntype NothingToShip implements DomainError {\n  code: String!\n  message: String!\n}\n\ntype OrderNotShippable implements DomainError {\n  code: String!\n  message: String!\n  status: OrderStatus!\n}\n\nunion ShipOrderResult = ShipmentCreated | NothingToShip | OrderNotShippable\n\ninput ReturnLineInput {\n  orderLineId: ID!\n  quantity: Int!\n}\n\ninput RequestReturnInput {\n  orderId: ID!\n  reason: String!\n  lines: [ReturnLineInput!]!\n}\n\ntype ReturnRequested {\n  return: Return!\n  order: Order!\n}\n\ntype ReturnQuantityExceededLine {\n  orderLineId: ID!\n  requested: Int!\n  returnable: Int!\n}\n\ntype ReturnQuantityExceeded implements DomainError {\n  code: String!\n  message: String!\n  lines: [ReturnQuantityExceededLine!]!\n}\n\ntype OrderNotReturnable implements DomainError {\n  code: String!\n  message: String!\n  status: OrderStatus!\n}\n\nunion RequestReturnResult = ReturnRequested | ReturnQuantityExceeded | OrderNotReturnable\n\ntype ReturnReceived {\n  return: Return!\n  order: Order!\n}\n\ntype ReturnNotReceivable implements DomainError {\n  code: String!\n  message: String!\n  status: ReturnStatus!\n}\n\nunion ReceiveReturnResult = ReturnReceived | ReturnNotReceivable\n\nenum StockChangeKind {\n  RECEIPT\n  ADJUSTMENT\n}\n\ninput AdjustInventoryInput {\n  skuId: ID!\n  warehouseId: ID!\n  kind: StockChangeKind!\n  \"RECEIPT requires a positive value. ADJUSTMENT can be negative (shrinkage, damage).\"\n  quantityDelta: Int!\n  reason: String!\n}\n\ntype InventoryAdjusted {\n  balance: InventoryBalance!\n  movement: InventoryMovement!\n}\n\ntype AdjustmentRejected implements DomainError {\n  code: String!\n  message: String!\n  onHand: Int!\n  reserved: Int!\n}\n\nunion AdjustInventoryResult = InventoryAdjusted | AdjustmentRejected\n\ninput UpdateSkuPriceInput {\n  skuId: ID!\n  priceMinor: Int!\n}\n\ntype SkuPriceUpdated {\n  sku: Sku!\n}\n\nunion UpdateSkuPriceResult = SkuPriceUpdated\n\ntype JobRetried {\n  job: Job!\n}\n\ntype JobNotRetryable implements DomainError {\n  code: String!\n  message: String!\n  status: JobStatus!\n}\n\nunion RetryJobResult = JobRetried | JobNotRetryable\n\ntype Mutation {\n  \"Customer. Validates prices, reserves stock atomically, starts simulated payment.\"\n  checkout(input: CheckoutInput!): CheckoutResult!\n  \"Owner (PENDING_PAYMENT or CONFIRMED, no shipments) or operator.\"\n  cancelOrder(orderId: ID!): CancelOrderResult!\n  \"Operator. Ships every confirmed reservation of the order in one warehouse.\"\n  shipOrder(input: ShipOrderInput!): ShipOrderResult!\n  \"Owner. Partial returns are allowed up to the shipped, not yet returned quantity.\"\n  requestReturn(input: RequestReturnInput!): RequestReturnResult!\n  \"Operator. Restocks returned units once and starts the simulated refund.\"\n  receiveReturn(returnId: ID!): ReceiveReturnResult!\n  \"Operator.\"\n  adjustInventory(input: AdjustInventoryInput!): AdjustInventoryResult!\n  \"Administrator.\"\n  updateSkuPrice(input: UpdateSkuPriceInput!): UpdateSkuPriceResult!\n  \"Administrator. Moves a FAILED job back to PENDING.\"\n  retryJob(jobId: ID!): RetryJobResult!\n}\n\n# ---------------------------------------------------------------------------\n# Subscriptions (graphql-ws protocol over WebSocket)\n# ---------------------------------------------------------------------------\n\ntype OrderStatusEvent {\n  \"Always re-read from PostgreSQL after the notification.\"\n  order: Order!\n  occurredAt: DateTime!\n}\n\ntype Subscription {\n  \"Owner, operator, or administrator. Emits the current order once on subscribe, then on every change.\"\n  orderUpdated(orderId: ID!): OrderStatusEvent!\n}\n";
